from __future__ import annotations

import math
from decimal import Decimal, InvalidOperation

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _check(value, step, method) -> None:
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method: {method!r}")
    if not step.is_finite() or step <= 0:
        raise ValueError("step must be positive")


def _signed_int(value: Decimal, exponent: int) -> tuple:
    """`value` as (sign, magnitude) in units of 10**exponent, with the remainder."""
    sign, digits, exp = value.as_tuple()
    magnitude = int("".join(map(str, digits)) or "0")
    return sign, magnitude, exp


def _divide(numerator: int, denominator: int, method: str, odd_is_up: bool = True) -> int:
    quotient, remainder = divmod(numerator, denominator)
    if method == DOWN or remainder == 0:
        return quotient
    twice = remainder * 2
    if twice > denominator:
        return quotient + 1
    if twice < denominator:
        return quotient
    if method == HALF_UP:
        return quotient + 1
    return quotient + (quotient % 2)


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    _check(value, step, method)
    if not value.is_finite():
        raise InvalidOperation("value must be finite")
    sign, magnitude, exp = _signed_int(value, 0)
    _, coefficient, step_exp = _signed_int(step, 0)
    if exp >= step_exp:
        numerator = magnitude * 10 ** (exp - step_exp)
        denominator = coefficient
    else:
        numerator = magnitude
        denominator = coefficient * 10 ** (step_exp - exp)
    multiples = _divide(numerator, denominator, method)
    digits = tuple(int(c) for c in str(multiples * coefficient))
    return Decimal((sign, digits, step_exp))


def allocate(amounts: list, step: Decimal) -> list:
    amounts = list(amounts)
    if not amounts:
        return []
    parts = [round_amount(a, step, DOWN) for a in amounts]
    whole = round_amount(sum(amounts, Decimal("0")), step, HALF_UP)
    zero = Decimal((0, (0,), step.as_tuple().exponent))
    rest = whole - sum(parts, zero)
    for i in range(len(parts) - 1, -1, -1):
        if amounts[i] != 0:
            parts[i] += rest
            break
    return parts


def legacy_cents(value: float, places: int = 2) -> float:
