        raise ValueError("places must be between 0 and 6")
    scale = 10**places
    return math.floor(value * scale + 0.5) / scale


def fixed(value, places: int, method: str = HALF_EVEN) -> str:
    if not isinstance(places, int) or isinstance(places, bool) or places < 0:
        raise ValueError("places must not be negative")
