import math
import unittest
from decimal import (
    ROUND_DOWN,
    ROUND_HALF_EVEN,
    ROUND_HALF_UP,
    Context,
    Decimal,
)

from meterbill import money


def D(text: str) -> Decimal:
    return Decimal(text)


class RoundAmount(unittest.TestCase):
    def test_exponent_of_step(self):
        self.assertEqual(str(money.round_amount(D("7"), D("0.05"), money.HALF_UP)), "7.00")
        self.assertEqual(str(money.round_amount(D("7.5"), D("1"), money.HALF_UP)), "8")

    def test_ties(self):
        self.assertEqual(money.round_amount(D("0.125"), D("0.01"), money.HALF_UP), D("0.13"))
        self.assertEqual(money.round_amount(D("0.125"), D("0.01"), money.HALF_EVEN), D("0.12"))
        self.assertEqual(money.round_amount(D("-0.125"), D("0.01"), money.HALF_UP), D("-0.13"))
        self.assertEqual(money.round_amount(D("0.175"), D("0.05"), money.HALF_EVEN), D("0.20"))
        self.assertEqual(money.round_amount(D("0.125"), D("0.05"), money.HALF_EVEN), D("0.10"))
        self.assertEqual(money.round_amount(D("-0.19"), D("0.10"), money.DOWN), D("-0.10"))

    def test_matches_quantize(self):
        ctx = Context(prec=60)
        methods = {money.HALF_UP: ROUND_HALF_UP, money.HALF_EVEN: ROUND_HALF_EVEN, money.DOWN: ROUND_DOWN}
        for text in ("0.005", "1.005", "2.5", "-2.5", "0.015", "123456.785", "-0.004", "0"):
            for method, mode in methods.items():
                self.assertEqual(
                    str(money.round_amount(D(text), D("0.01"), method)),
                    str(ctx.quantize(D(text), D("0.01"), rounding=mode)),
                )

    def test_errors(self):
        with self.assertRaises(TypeError):
            money.round_amount(1.5, D("0.01"), money.DOWN)
        with self.assertRaises(ValueError):
            money.round_amount(D("1"), D("0.01"), "up")
        with self.assertRaises(ValueError):
            money.round_amount(D("1"), D("0"), money.DOWN)


class Allocate(unittest.TestCase):
    def test_sums_to_rounded_whole(self):
        amounts = [D("1.005"), D("1.005"), D("0")]
        parts = money.allocate(amounts, money.CENT)
        self.assertEqual(parts, [D("1.00"), D("1.01"), D("0.00")])
        self.assertEqual(sum(parts), money.round_amount(sum(amounts), money.CENT, money.HALF_UP))

    def test_empty_and_unchanged(self):
        self.assertEqual(money.allocate([], money.CENT), [])
        amounts = [D("0.333")]
        money.allocate(amounts, money.CENT)
        self.assertEqual(amounts, [D("0.333")])


class Legacy(unittest.TestCase):
    def test_settle(self):
        self.assertEqual(money.legacy_cents(-4.255), math.floor(-4.255 * 100 + 0.5) / 100)
        self.assertEqual(money.legacy_cents(2.5, 0), 3.0)
        self.assertEqual(money.legacy_cents(1.23456, 4), 1.2346)


class Fixed(unittest.TestCase):
    def test_float(self):
        self.assertEqual(money.fixed(2.675, 2), "2.67")
        self.assertEqual(money.fixed(2.5, 0), "2")
        with self.assertRaises(ValueError):
            money.fixed(2.5, 0, money.HALF_UP)

    def test_decimal(self):
        self.assertEqual(money.fixed(D("2.675"), 2, money.HALF_UP), "2.68")
        self.assertEqual(money.fixed(D("2.5"), 0), "2")
        self.assertEqual(money.fixed(D("1E+3"), 1), "1000.0")
        self.assertEqual(money.fixed(D("0.00001"), 3, money.DOWN), "0.000")


